        /// <summary>
        /// This function will return a current context object
        /// </summary>
        /// <returns>Current context object</returns>
        [HttpPost]
        public JsonResult GetContextObject()
        {
            // Init context for add new supper
            IRequestContext currentContext = new RequestContext()
            {
                RoleId = 0,// role of the member do insert
                TargetRoleId = 4,// role of the super be inserted
                FormId = FormType.Add,
                Language = "En",
                LangKey = "E",
                SettingStatus = WebSettings.SettingStatus
            };
            // Format json return
            return Json(JsonConvert.SerializeObject(currentContext, Formatting.Indented, GetJsonSerializerSetting()));
        }

        /// <summary>
        /// This function will add new customer and redirect to update page if add successful
        /// </summary>
        /// <param name="stringcustomer">String will be deserialized to a customer object</param>
        /// <param name="currentContext">Current context</param>
        /// <returns>Return a result message</returns>        
        [HttpPost]
        [AuthenticateHost]
        public JsonResult DoAddNewSuper(string stringcustomer, RequestContext currentContext, string code)
        {
            Fanex.PTEngine.BusinessObjects.Result result;
            try
            {
                ICustomer customer = GetCustomerFromDeserializeJsonString(stringcustomer);
                customer.Password = Fanex.Tarus.Security.Services.Encryptor.Decrypt(customer.Password, code);

                // Check Permission for finace
                result = CheckPermissionInsert(customer.IsInternal);
                if (result.ErrorCode != "0")
                    return Json(result);

                // Save currency id
                string currency = customer.CurrencyId.ToString();
                // Do insert new super
                int superId = 0;
                currentContext.AdminId = AppSession.AccId;
                customer.Language = "E";
                currentContext.IP = System.Web.HttpContext.Current.Request.UserHostAddress;
                currentContext.SystemId = SystemId;

                result = _customerService.AddNewSuper(customer, currentContext, out superId);

                if (superId > 0 && result.ErrorCode == "0")
                {
                    _serviceBase.AddMsgAfterCreateNewSMA(new AddMsgAfterCreateNewSMACriteria(superId, 0 , (int)Role.Super));
                }

                if (superId > 0 && result.ErrorCode == "0" && IsNeedToUpdateAutoTransferAndDateLimit(customer.SiteName, customer.CurrencyId))
                {
                    result = UpdateDefaultValueAutoTransferAndDateLimitForSpecialSiteSuper(superId, customer.UserName);
                }

                // DedirectToEditPage
                if (string.IsNullOrWhiteSpace(result.ErrorCode) || result.ErrorCode == "0")
                {
                    string strUrl = "Customer/V2/UpdatePT.aspx?custid=" + superId + "&insert=true&roleid=4&uplineid=0&exchangeId=" + currency;
                    result.ErrorMessage = strUrl;
                    Thread.Sleep(3000);
                    AutoInsertNG2(superId, customer.UserName, 4, false, true, superId, customer.CurrencyId, AppSession.AccId);
                }
            }
            catch (Exception ex)
            {
                LogExtensions.ExceptionHandler(ex);
                result = new Fanex.PTEngine.BusinessObjects.Result
                {
                    ErrorCode = "1000",
                    ErrorMessage = ex.Message
                };
            }

            // Return result
            return Json(result);
        }

        [HttpPost]
        public ActionResult GetSuperPrefixes(SuperPrefixQuery query)
            => Json(_customerSettingService.GetSuperPrefixes(new SuperPrefixCriteria
            {
                GroupName = query.GroupName,
                Prefix = query.Prefix,
                AllowNewSuper = query.AllowNewSuper
            }), JsonRequestBehavior.DenyGet);

        /// <summary>
        /// This function will check a customer pemission for insert function
        /// </summary>
        /// <returns>Result a result content error message or not</returns>
        [NonAction]
        public Fanex.PTEngine.BusinessObjects.Result CheckPermissionInsert(bool isInternal)
        {
            var result = new PTEngine.BusinessObjects.Result
            {
                ErrorCode = "0",
                ErrorMessage = "Success"
            };

            if (AppSession.SYSTEM.ToLower() != Enumerations.AccountingSystem.Accounting.ToString().ToLower())
            {
                result.ErrorCode = "1000";
                result.ErrorMessage = "You are not authorized on this function";
                return result;
            }

            if (isInternal)
            {
                if (!_customerSettingService.CheckPermissionFinance())
                {
                    result.ErrorCode = "1000";
                    result.ErrorMessage = "You're not authorized to create Finance (Internal) account.";
                }
            }

            return result;
        }

        private void AutoInsertNG2(int custId, string username, int roleId, bool disabledUpline, bool syncUpline, int uplineId, int currencyId, int userId)
        {
            if (syncUpline)
            {
                ING2StatusService syncService = new NG2StatusService();
                syncService.AutoInsertAccount(custId, username, (RoleId)roleId, uplineId, disabledUpline, SiteId.NAP, currencyId, userId, SystemId, WebSettings.SettingStatus);
            }
        }

        private PTEngine.BusinessObjects.Result UpdateDefaultValueAutoTransferAndDateLimitForSpecialSiteSuper(int superId, string UserName)
        {
            var result = new PTEngine.BusinessObjects.Result();
            var updateTransferResult = _autoTransferAllService.InsertAgentsFromPopup(new InsertAgentsFromPopupCriteria
            {
                UserName = UserName,
                IP = System.Web.HttpContext.Current.Request.UserHostAddress,
                TransferType = 2,
                UserID = AppSession.AccId
            });

            if (updateTransferResult.ErrorCode != 0)
            {
                result.ErrorCode = updateTransferResult.ErrorCode.ToString();
                result.ErrorMessage = updateTransferResult.ErrorMessage;
            }

            if (updateTransferResult.ErrorCode == 0)
            {
                var udpateDateLimitResult = _customerDateLimitService.Update(new UpdateCustomerDateLimitCriteria
                {
                    CustIds = superId.ToString(),
                    UserNames = UserName,
                    Choice = 2,
                    LimitDays = 33,
                    UserId = AppSession.AccId
                });

                if (udpateDateLimitResult.ErrorCode != 0)
                {
                    result.ErrorCode = udpateDateLimitResult.ErrorCode.ToString();
                    result.ErrorMessage = udpateDateLimitResult.ErrorMessage;
                }
            }

            return result;
        }

        private bool IsNeedToUpdateAutoTransferAndDateLimit(string siteName, int currencyId) => siteName.Equals("789y") && currencyId != 20;
    }
